import {esc,icon,download,formatDate} from './ui.mjs';
import {feedbackKey,feedbackTypes,relatedFeatures,helpCategories,articles,searchHelp,normalizeFeedback,feedbackText} from './help-model.mjs';
const $=s=>document.querySelector(s);let active;
export function clearHelpWork(){active=null;}
export const helpHasWork=()=>!!active?.dirty;
window.addEventListener('beforeunload',e=>{if(helpHasWork()){e.preventDefault();e.returnValue='';}});
const comparable=v=>JSON.stringify([v.type,v.feature,v.content]);
function message(text,error=false){const el=$('#help-feedback-status');if(el){el.textContent=text;el.classList.toggle('error',error);}}
function save(s){if(s.loadError){message('旧草稿无法读取，已停止覆盖。请先导出当前输入。',true);return false;}if(!s.values.content.trim()){message('请先填写问题描述。',true);return false;}try{const previous=localStorage.getItem(feedbackKey);if(previous!==s.savedRaw)throw Error('反馈草稿已在其他窗口变化。请先导出当前文本，再重新打开本页。');const value={...s.values,savedAt:new Date().toISOString()};localStorage.setItem(feedbackKey,JSON.stringify(value));s.values=value;s.savedRaw=JSON.stringify(value);s.original=comparable(value);s.dirty=false;message('草稿已本地保存 · '+formatDate(value.savedAt));s.ctx.notify('已保存反馈草稿，尚未发送。');return true;}catch(error){message(error.message.includes('其他窗口')?error.message:'保存失败，请检查浏览器存储空间；当前输入仍保留，可导出文本。',true);return false;}}
export function helpRouteGuard(target){if(!helpHasWork())return true;const s=active;s.ctx.modal('反馈草稿尚未保存','<p class="hub-description">可以保存本地草稿后离开，或放弃本次未保存的修改。导出文本不会自动保存草稿。</p><div class="settings-actions"><button class="btn secondary" id="help-stay">继续填写</button><button class="btn secondary" id="help-discard">放弃修改</button><button class="btn primary" id="help-save-leave">保存并离开</button></div>');$('#help-stay').onclick=()=>$('#workspace-dialog').close();$('#help-discard').onclick=()=>{s.dirty=false;$('#workspace-dialog').close();location.hash=target;};$('#help-save-leave').onclick=()=>{if(save(s)){$('#workspace-dialog').close();location.hash=target;}};return false;}
export function mountHelp(ctx){let raw=null,values,loadError=false;try{raw=localStorage.getItem(feedbackKey);values=normalizeFeedback(raw?JSON.parse(raw):{});}catch{values=normalizeFeedback();loadError=true;}const s=active={ctx,values,savedRaw:raw,original:comparable(values),dirty:false,query:'',category:'all',faq:'all'};$('.dashboard').onclick=null;$('.dashboard').innerHTML=`<div class="hub-heading"><div><h1>帮助与反馈</h1><p>找到答案，让研究顺利进行。</p></div></div><div class="help-layout"><div class="help-primary"><section class="help-search-panel"><h2>你想了解什么？</h2><form id="help-search-form"><label class="sr-only" for="help-search">搜索帮助</label><div>${icon('search',20)}<input id="help-search" type="search" maxlength="100" placeholder="搜索问题，例如：上传失败、报告导出、备份恢复"><button class="btn primary">搜索</button></div></form><p>热门搜索： <button data-help-query="新手">新手入门</button><button data-help-query="上传">文件上传</button><button data-help-query="备份">数据备份</button></p></section><section class="help-guides"><header><h2>使用指南</h2><button id="help-all" hidden>查看全部指南 →</button></header><div class="help-category-grid">${helpCategories.map(c=>`<button class="card help-category" data-help-category="${c.id}" aria-pressed="false"><span class="more-icon ${c.color}">${icon(c.icon,24)}</span><span><b>${c.title}</b><small>${c.description}</small></span>${icon('arrow',14)}</button>`).join('')}</div></section><section class="card help-results" id="help-results" hidden aria-label="帮助文章"><div id="help-result-list" aria-live="polite"></div></section><section class="card help-faq"><h2>常见问题</h2><div class="help-faq-tabs" role="group" aria-label="常见问题分类">${[['all','全部'],['upload','上传与解析'],['data','保存与备份'],['detection','检测与报告']].map(([id,label])=>`<button data-help-faq="${id}" aria-pressed="${id==='all'}">${label}</button>`).join('')}</div><div id="help-faq-list"></div></section></div><aside class="help-aside"><section class="card help-feedback"><header><h2>反馈草稿</h2><span class="help-pill">本地保存</span></header><p>找不到答案？记录你遇到的问题。</p><form id="help-feedback-form" class="hub-form"><label for="help-feedback-type">反馈类型</label><select id="help-feedback-type" name="type">${feedbackTypes.map(v=>`<option ${values.type===v?'selected':''}>${v}</option>`).join('')}</select><label for="help-feedback-feature">相关功能</label><select id="help-feedback-feature" name="feature">${relatedFeatures.map(v=>`<option ${values.feature===v?'selected':''}>${v}</option>`).join('')}</select><label for="help-feedback-content">问题描述</label><textarea id="help-feedback-content" name="content" rows="5" maxlength="3000" placeholder="请说明操作步骤、遇到的问题和期望结果…">${esc(values.content)}</textarea><small id="help-feedback-count">${values.content.length}/3000</small><p class="help-private-note">不要填写密码或私人研究正文。</p><div class="help-feedback-actions"><button class="btn primary" type="submit">保存草稿</button><button class="btn secondary" type="button" id="help-feedback-export">导出文本</button></div></form><p id="help-feedback-status" role="status" aria-live="polite"></p><footer>${icon('help',16)} 草稿仅保存在当前浏览器，尚未发送至 PaperKnow。</footer></section><section class="card help-service"><h2>当前服务状态</h2><div>${icon('grid',19)}<span>本地工具</span><b class="available">● 可用</b></div><div>${icon('pen',19)}<span>在线 AI</span><b>● 待接入</b></div><div>${icon('folder',19)}<span>云端同步</span><b>● 待接入</b></div><a href="#membership">查看功能开放范围 →</a><small>各工具能力以对应页面说明为准。</small></section><section class="help-backup">${icon('shield',25)}<div><b>先保护好你的研究资料</b><p>更换设备或清理浏览器前，请导出工作空间备份。</p><a href="#settings/data">前往数据与备份 →</a></div></section></aside></div>`;
renderFaq(s);message(loadError?'旧反馈草稿无法读取，请勿覆盖。请先保留浏览器数据并导出当前输入。':values.savedAt?'草稿已本地保存 · '+formatDate(values.savedAt):'尚无本地反馈草稿。',loadError);s.loadError=loadError;
$('#help-search-form').onsubmit=e=>{e.preventDefault();s.query=$('#help-search').value.trim();s.category='all';renderResults(s);};$('.help-layout').addEventListener('click',e=>{const query=e.target.closest('[data-help-query]');if(query){s.query=query.dataset.helpQuery;s.category='all';$('#help-search').value=s.query;renderResults(s);return;}const category=e.target.closest('[data-help-category]');if(category){s.category=s.category===category.dataset.helpCategory?'all':category.dataset.helpCategory;s.query='';$('#help-search').value='';renderResults(s);return;}const faq=e.target.closest('[data-help-faq]');if(faq){s.faq=faq.dataset.helpFaq;renderFaq(s);return;}const article=e.target.closest('[data-help-article]');if(article)openArticle(article.dataset.helpArticle,ctx);});$('#help-all').onclick=()=>{s.query='';s.category='all';$('#help-search').value='';renderResults(s);};$('#help-feedback-form').oninput=()=>{s.values=normalizeFeedback({...s.values,...Object.fromEntries(new FormData($('#help-feedback-form')))});s.dirty=comparable(s.values)!==s.original;$('#help-feedback-count').textContent=s.values.content.length+'/3000';message(s.dirty?'有未保存的修改':s.values.savedAt?'草稿已本地保存 · '+formatDate(s.values.savedAt):'尚无本地反馈草稿。');};$('#help-feedback-form').onsubmit=e=>{e.preventDefault();if(s.loadError){message('旧草稿无法读取，已停止覆盖。请先导出当前输入。',true);return;}save(s);};$('#help-feedback-export').onclick=()=>{try{download('PaperKnow-反馈草稿.txt',feedbackText(s.values));ctx.notify('已发起反馈文本下载，尚未发送，也不会自动保存草稿。');}catch(error){message(error.message,true);}};
}
function renderResults(s){const shown=s.query||s.category!=='all',rows=searchHelp(s.query,s.category);$('#help-results').hidden=!shown;$('#help-all').hidden=!shown;document.querySelectorAll('[data-help-category]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.helpCategory===s.category));if(!shown)return;$('#help-result-list').innerHTML=`<header><h3>${s.query?'搜索结果':esc(helpCategories.find(c=>c.id===s.category)?.title||'使用指南')}</h3><span>${rows.length} 篇帮助</span></header>${rows.length?rows.map(a=>`<button class="help-result" data-help-article="${a.id}"><span><b>${esc(a.title)}</b><small>${esc(a.summary)}</small></span>${icon('arrow',16)}</button>`).join(''):'<div class="help-no-results"><b>暂未找到相关帮助</b><p>试试“上传”“查重”“备份”等关键词，或在右侧记录反馈草稿。</p></div>'}`;}
function renderFaq(s){const ids=s.faq==='all'?['upload-pdf','data-location','detection-meaning','data-backup']:articles.filter(a=>a.faq===s.faq||(s.faq==='detection'&&a.category==='detection')).map(a=>a.id);$('#help-faq-list').innerHTML=ids.map((id,i)=>{const a=articles.find(a=>a.id===id);return `<details ${i===0?'open':''}><summary>${esc(a.title)}</summary><div><p>${esc(a.summary)}</p><button data-help-article="${a.id}">查看完整步骤 →</button></div></details>`;}).join('');document.querySelectorAll('[data-help-faq]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.helpFaq===s.faq));}
function openArticle(id,ctx){const a=articles.find(a=>a.id===id);if(!a)return;ctx.modal(a.title,`<div class="help-article"><p class="help-article-summary">${esc(a.summary)}</p><ol>${a.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><aside>${icon('help',18)}<p>${esc(a.note)}</p></aside>${a.action?`<a class="btn primary" href="${a.action}">${a.actionLabel} ${icon('arrow',16)}</a>`:''}</div>`);}
